/* POC governance: dummy targets, traceable results and explicit acceptance evidence. */
const POC_ROLES=['AO','SPV','Kepala Kantor','Manajemen Pusat','Superadmin'];
let pocPeriod=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Makassar',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()).slice(0,7),pocScope='branch';
const pocPerformanceCache=new Map(),pocEvidenceCache=new Map();
function pocReadOnly(){return !journey&&['Kepala Kantor','Manajemen Pusat'].includes(authUser?.role)}
function pocCentral(){return ['Manajemen Pusat','Superadmin'].includes(authUser?.role)}
function pocKey(kind){return [kind,authUser?.id,authUser?.role,activeBranch,serverRevision,pocPeriod,pocScope].join('|')}
function pocEffectiveScope(){return pocCentral()?pocScope:'branch'}
function pocCall(name,...args){return leadCall(name,...args)}
function pocUpdate(key,value){if(key==='period')pocPeriod=value;else if(key==='scope')pocScope=value;renderContent();persistWorkspaceLocation()}
async function pocLoadPerformance(force=false){if(!authUser||journey||!activeBranch)return;const key=pocKey('performance'),prior=pocPerformanceCache.get(key);if(prior&&!force)return;pocPerformanceCache.set(key,{loading:true});const actorId=authUser.id,branch=activeBranch;try{const data=await api('performance?period='+encodeURIComponent(pocPeriod)+'&scope='+pocEffectiveScope());if(authUser?.id!==actorId||activeBranch!==branch)return;pocPerformanceCache.set(key,{data})}catch(e){pocPerformanceCache.set(key,{error:e.message})}finally{if(pocPerformanceCache.size>12)for(const k of [...pocPerformanceCache.keys()].slice(0,-8))pocPerformanceCache.delete(k);if(authUser?.id===actorId&&activeBranch===branch&&['Monitoring','Target & Kinerja','Home'].includes(view)&&key===pocKey('performance'))renderContent()}}
function pocMoney(value){return rup(Number(value)||0)}
function pocProgress(actual,target){if(!Number(target))return '<span class="poc-muted">'+(actual?'Realisasi ada; tanpa target nominal':'Tanpa target nominal')+'</span>';const pct=Math.round(actual/target*100);return '<span class="poc-progress"><i style="width:'+Math.min(100,pct)+'%"></i></span><small>'+pct+'% dari '+pocMoney(target)+'</small>'}
function pocCell(actual,target){return '<strong>'+pocMoney(actual)+'</strong>'+pocProgress(actual,target)}
function pocPerformanceControls(){return '<div class="poc-performance-filters"><label>Bulan kinerja<input aria-label="Bulan target dan realisasi" type="month" value="'+E(pocPeriod)+'" onchange="pocUpdate(\'period\',this.value)"></label>'+(pocCentral()?'<label>Cakupan<select aria-label="Cakupan kinerja" onchange="pocUpdate(\'scope\',this.value)"><option value="branch" '+(pocScope!=='all'?'selected':'')+'>Cabang aktif</option><option value="all" '+(pocScope==='all'?'selected':'')+'>Semua cabang dalam akses saya</option></select></label>':'<span>'+E(activeBranch)+'</span>')+btn('Perbarui','pocLoadPerformance(true)')+'</div>'}
function pocPerformancePanel(full=false){const entry=pocPerformanceCache.get(pocKey('performance')),data=entry?.data;const controls=pocPerformanceControls();if(!data)return '<section class="panel poc-performance"><h2>Target & Realisasi</h2>'+controls+'<p role="status">'+E(entry?.error||'Memuat target dan realisasi dummy…')+'</p></section>';const total=k=>data.branchRows.reduce((n,r)=>n+Number(r[k]||0),0),target=k=>data.branchRows.reduce((n,r)=>n+Number(r.target[k]||0),0);return '<section class="panel poc-performance"><div class="poc-panel-title"><div><small>KINERJA BISNIS · DUMMY POC</small><h2>Target & Realisasi</h2><p>Realisasi berasal dari konfirmasi nominal, tanggal dan referensi pada Opportunity Berhasil. Nominal pipeline tidak dihitung sebagai realisasi.</p></div>'+(full?'':btn('Lihat rincian',"go('Target & Kinerja')"))+'</div>'+controls+'<div class="poc-kpis">'+[['Kredit','credit'],['Dana','funding'],['Layanan','service']].map(([label,key])=>'<article><span>Realisasi '+label+'</span>'+pocCell(total(key),target(key))+'</article>').join('')+'</div><p class="hint">Target cabang adalah penjumlahan target AO. Kredit, dana dan layanan ditampilkan terpisah; bukan total pendapatan Bank.</p><div class="scrolltable"><table class="datatable poc-table"><thead><tr><th>Cabang</th><th>Kredit</th><th>Dana</th><th>Layanan</th><th>Task selesai / target</th><th>Task overdue</th></tr></thead><tbody>'+data.branchRows.map(r=>'<tr><td><strong>'+E(r.branch)+'</strong><small>'+r.configured+' / '+r.aoCount+' AO memiliki target</small></td><td>'+pocCell(r.credit,r.target.credit)+'</td><td>'+pocCell(r.funding,r.target.funding)+'</td><td>'+pocCell(r.service,r.target.service)+'</td><td>'+r.completed+' / '+r.target.completed+'</td><td>'+r.overdue+'</td></tr>').join('')+'</tbody></table></div>'+(data.unconfirmedWon.length?'<div class="poc-warning"><strong>'+data.unconfirmedWon.length+' Opportunity Won belum terkonfirmasi nominal realisasinya.</strong><p>Tidak dimasukkan ke pencapaian sampai nominal, tanggal dan referensi diisi.</p></div>':'')+(full&&data.unconfirmedWon.length?'<details class="poc-unconfirmed"><summary>Lihat Won yang belum terkonfirmasi</summary>'+data.unconfirmedWon.map(r=>'<article class="poc-finding"><strong>'+E(r.name)+'</strong><p>'+E(r.owner)+' · '+E(r.branch)+'</p>'+btn(r.branch===activeBranch?'Buka Opportunity':'Pilih cabang',r.branch===activeBranch?pocCall('go','Opportunity detail',r.id):'openBranchSelection()')+'</article>').join('')+'</details>':'')+(full?'<h3>Target dan pencapaian AO</h3><div class="scrolltable"><table class="datatable poc-table"><thead><tr><th>AO / Cabang</th><th>Kredit</th><th>Dana</th><th>Layanan</th><th>Task selesai / target</th><th>Target</th></tr></thead><tbody>'+data.rows.map(r=>'<tr><td><strong>'+E(r.name)+'</strong><small>'+E(r.branch)+'</small></td><td>'+pocCell(r.credit,r.target?.credit)+'</td><td>'+pocCell(r.funding,r.target?.funding)+'</td><td>'+pocCell(r.service,r.target?.service)+'</td><td>'+r.completed+' / '+(r.target?.completed??'—')+'</td><td>'+(data.canSetTargets&&r.branch===activeBranch&&r.eligibleTarget?btn('Atur target',pocCall('pocTargetForm',r.id)):'<small>Akses baca</small>')+'</td></tr>').join('')+'</tbody></table></div><h3>Bukti realisasi per Opportunity</h3><div class="poc-contributions">'+(data.contributions.map(r=>'<article><div><strong>'+E(r.name)+'</strong><small>'+E(r.owner)+' · '+E(r.branch)+' · '+E(r.product)+'</small><small>'+E(r.at)+' · '+E(r.reference)+'</small></div><div><strong>'+pocMoney(r.amount)+'</strong>'+btn(r.branch===activeBranch?'Buka Opportunity':'Pilih cabang',r.branch===activeBranch?pocCall('go','Opportunity detail',r.id):'openBranchSelection()')+'</div></article>').join('')||empty('Belum ada realisasi terkonfirmasi pada periode ini.'))+'</div>':'')+'<p class="poc-source">'+E(data.source)+'</p></section>'}
function pocPerformanceScreen(){return titleBlock('Target & Kinerja','Bandingkan target dan realisasi yang dapat ditelusuri, sesuai role dan cabang.')+pocPerformancePanel(true)}
function pocTargetForm(ownerId){const data=pocPerformanceCache.get(pocKey('performance'))?.data,row=data?.rows.find(r=>r.id===ownerId&&r.branch===activeBranch);if(!row||!data.canSetTargets)return toast('Target hanya dapat diubah Kepala Kantor / Superadmin pada cabang aktif.');const target=row.target;modal('Target AO · '+E(row.name),'<p>'+E(activeBranch)+' · '+E(pocPeriod)+'</p>'+field('Target kredit (Rp)','credit',target?.credit??0,'number',true)+field('Target dana (Rp)','funding',target?.funding??0,'number',true)+field('Target layanan (Rp)','service',target?.service??0,'number',true)+field('Target Task selesai','completed',target?.completed??0,'number',true)+area('Alasan penetapan / perubahan','note','',true)+(target?.history?.length?'<details><summary>Riwayat target</summary>'+target.history.slice().reverse().map(h=>'<p>'+E(fmt(h.at))+' · '+E(h.by)+'<br>'+E(h.note)+'</p>').join('')+'</details>':''),f=>{const button=document.querySelector('#form > .actions > .primary');if(button?.disabled)return false;if(button)button.disabled=true;api('performance/targets',{...f,ownerId,period:pocPeriod,branch:activeBranch,before:target||null}).then(async()=>{document.querySelector('#modal').close();await pocLoadPerformance(true);toast('Target tersimpan')}).catch(e=>{document.querySelector('#formerror').textContent=e.message;if(button)button.disabled=false});return false})}
function pocRealizationForm(id){const o=opp(id);if(!o||o.outcome!=='Won'||pocReadOnly())return toast('Realisasi dicatat AO pemilik / SPV / Superadmin pada Opportunity Berhasil.');modal('Konfirmasi realisasi dummy',detailFacts([['Opportunity',o.name],['Produk',o.product],['Nilai pipeline indikatif',rup(o.value)]])+field('Nominal realisasi (Rp)','amount',o.realizedAmount??'','number',true)+field('Tanggal realisasi','date',o.realizedAt||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Makassar',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),'date',true)+field('Referensi realisasi dummy','reference',o.realizationReference||o.reference||'','text',true)+area('Catatan konfirmasi / koreksi','note','',true)+'<p class="hint">Konfirmasi manual dengan data dummy. Tidak melakukan transaksi atau mengambil data dari Bank.</p>',f=>{const submit=document.querySelector('#form > .actions > .primary');if(submit?.disabled)return false;if(submit)submit.disabled=true;api('performance/realization',{opp:id,...f,before:{amount:o.realizedAmount??null,date:o.realizedAt??null,reference:o.realizationReference??null}}).then(async()=>{document.querySelector('#modal').close();applyServer(await api('state'));pocPerformanceCache.clear();toast('Realisasi dummy tersimpan')}).catch(e=>{const error=document.querySelector('#formerror');if(error)error.textContent=e.message;else toast(e.message)}).finally(()=>{if(submit?.isConnected)submit.disabled=false});return false})}
const pocUatCacheKey=()=>[authUser?.id,authUser?.role,activeBranch,serverRevision,pocEffectiveScope()].join('|');
async function pocLoadEvidence(force=false){if(!authUser||authUser.role==='AO'||journey)return;const key=pocUatCacheKey();if(pocEvidenceCache.has(key)&&!force)return;pocEvidenceCache.set(key,{loading:true});try{const [checks,uat,validation]=await Promise.all([api('poc/checks?scope='+pocEffectiveScope()),api('poc/uat'),fetch('poc-validation.json?v=20261124-poc-readiness',{cache:'no-store'}).then(r=>r.ok?r.json():null).catch(()=>null)]);pocEvidenceCache.set(key,{checks,uat,validation})}catch(e){pocEvidenceCache.set(key,{error:e.message})}finally{if(pocEvidenceCache.size>8)pocEvidenceCache.delete(pocEvidenceCache.keys().next().value);if(key===pocUatCacheKey()&&view==='Kesiapan POC')renderContent()}}
function pocEvidenceScreen(){const entry=pocEvidenceCache.get(pocUatCacheKey()),checks=entry?.checks,uat=entry?.uat;let html=titleBlock('Kesiapan POC','Data dummy, pemeriksaan konsistensi, dan bukti penerimaan yang belum/telah diuji.',btn('Perbarui','pocLoadEvidence(true)'));if(!checks)return html+empty(entry?.error||'Memuat pemeriksaan POC…');return html+(entry.validation?'<section class="panel"><h2>Verifikasi otomatis implementasi</h2><p>'+entry.validation.passed+' / '+entry.validation.total+' kelompok pengujian lolos · '+E(fmt(entry.validation.checkedAt))+'</p><p class="hint">Lingkungan uji terisolasi D1/R2. Bukan hasil UAT Bank dan bukan load test hosting live.</p></section>':'')+'<section class="panel"><h2>Batas dan kesesuaian POC</h2>'+checks.boundaries.map(b=>'<article class="poc-boundary"><strong>'+E(b.requirement)+'</strong>'+badge(b.status)+'<p>'+E(b.note)+'</p></article>').join('')+'</section><section class="panel"><h2>Pemeriksaan konsistensi otomatis</h2>'+badge(checks.passed?'Tidak ditemukan inkonsistensi relasi':'Ada temuan yang perlu diperbaiki')+'<p>'+E(fmt(checks.checkedAt))+' · '+Object.entries(checks.records).map(([k,v])=>E(k)+': '+v).join(' · ')+'</p>'+[...checks.errors,...checks.warnings].map(x=>'<article class="poc-finding"><strong>'+E(x.id)+' · '+E(x.code)+'</strong><p>'+E(x.note)+'</p></article>').join('')+'<p class="hint">Pemeriksaan otomatis memeriksa relasi dan konsistensi data. Ini bukan pengganti UAT bersama Bank.</p></section><section class="panel"><h2>Skenario UAT · '+E(uat.branch)+'</h2><p>Hasil awal Belum diuji. Superadmin mencatat hasil setelah menjalankan skenario, beserta bukti / temuan.</p><div class="poc-uat-list">'+uat.scenarios.map(s=>'<article><div class="recordtop"><h3>'+E(s.title)+'</h3>'+badge(s.result?.status||'Belum diuji')+'</div><p>'+E(s.steps)+'</p><p><strong>Hasil yang diharapkan:</strong> '+E(s.expected)+'</p>'+(s.result?'<small>'+E(s.result.by)+' · '+E(fmt(s.result.at))+'</small><p>'+E(s.result.note)+'</p>':'')+(uat.canRecord?btn('Catat hasil',pocCall('pocRecordUat',s.id)):'')+'</article>').join('')+'</div>'+btn('Download hasil evaluasi','pocExportEvidence()')+'</section><section class="panel"><h2>Akun dan cakupan akses</h2><div class="scrolltable"><table class="datatable"><thead><tr><th>Akun / User ID</th><th>Role</th><th>Cabang</th></tr></thead><tbody>'+checks.accounts.map(m=>'<tr><td>'+E(m.name)+'<small>'+E(m.id)+'</small></td><td>'+E(m.role)+'</td><td>'+E(m.branches.join(' · '))+'</td></tr>').join('')+'</tbody></table></div><p class="hint">Kepala Kantor dan Manajemen Pusat membaca data operasional. Kepala Kantor dapat menetapkan target cabangnya; pengaturan akun/master tetap Superadmin.</p></section>'}
function pocRecordUat(id){const entry=pocEvidenceCache.get(pocUatCacheKey()),s=entry?.uat.scenarios.find(s=>s.id===id);if(!entry?.uat.canRecord||!s)return;modal('Catat UAT · '+E(s.title),'<p>'+E(s.expected)+'</p>'+select('Hasil pengujian','status',['Belum diuji','Lulus','Gagal'],s.result?.status||'Belum diuji')+area('Bukti / temuan pengujian','note',s.result?.note||'',true),f=>{const submit=document.querySelector('#form > .actions > .primary');if(submit?.disabled)return false;if(submit)submit.disabled=true;api('poc/uat',{scenario:id,...f,revision:s.result?.revision||0}).then(async()=>{document.querySelector('#modal').close();await pocLoadEvidence(true);toast('Hasil UAT tercatat')}).catch(e=>{const error=document.querySelector('#formerror');if(error)error.textContent=e.message;else toast(e.message)}).finally(()=>{if(submit?.isConnected)submit.disabled=false});return false})}
function pocExportEvidence(){const entry=pocEvidenceCache.get(pocUatCacheKey());if(!entry?.checks)return;const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),branch:activeBranch,checks:entry.checks,uat:entry.uat,automatedValidation:entry.validation||null},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='BPD-Bali-POC-Evaluasi.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const pocMutatingAction=/\b(createLead|leadPipelineActions|leadBeginQualification|qualify|assessment|leadIdentityEdit|leadEditSource|convertLeadCustomer|closeLead|newOpp|changeStage|closeOpp|bankSelectStage|editOpportunity|reopenRecord|returnLeadQualified|newTask|editTask|cancelTask|activityForm|approveVisit|reviewCorrection|reassign|directCustomer|changeCustomerStatus|c360Edit|c360ContextEdit|c360UploadForm|c360CreateOpportunity|c360LaunchCrossSell|c360Task|applicationForm|masterForm|reorderStage|escalationForm|leadWorkflowConfig|pocRealizationForm)\s*\(/;
function pocAccessUI(){if(!authUser||journey)return;const root=document.querySelector('#app');if(!root)return;if(pocReadOnly()){for(const b of root.querySelectorAll('button[onclick]'))if(pocMutatingAction.test(b.getAttribute('onclick')||''))b.remove();if(!root.querySelector('.poc-readonly'))root.insertAdjacentHTML('afterbegin','<div class="poc-readonly" role="status">'+E(authUser.role)+' · Akses baca data operasional'+(authUser.role==='Kepala Kantor'?'; dapat mengatur target cabang aktif.':'.')+'</div>');}const nav=document.querySelector('#nav');if(nav&&!mobile&&!nav.querySelector('[data-poc-target]')){const b=document.createElement('button');b.dataset.pocTarget='1';b.textContent='Target & Kinerja';b.onclick=()=>go('Target & Kinerja');b.className=view===b.textContent?'active':'';nav.append(b)}if(nav&&!mobile&&authUser.role!=='AO'&&!nav.querySelector('[data-poc-evidence]')){const b=document.createElement('button');b.dataset.pocEvidence='1';b.textContent='Kesiapan POC';b.onclick=()=>go('Kesiapan POC');b.className=view===b.textContent?'active':'';nav.append(b)}}
const pocReopenBefore=reopenRecord;
reopenRecord=function(kind,id){if(kind!=='opp')return pocReopenBefore(kind,id);const o=opp(id);if(!o||o.outcome==='Aktif')return toast('Opportunity tidak tersedia / masih aktif.');modal('Buka kembali Opportunity',area('Alasan pembukaan kembali','reason','',true)+'<p class="hint">Opportunity kembali ke tahap proses terakhir yang aktif. Riwayat hasil dan Task lama tetap disimpan; buat Task tindak lanjut baru.</p>',f=>{const stage=stageDefs().find(s=>s.active&&s.type==='process'&&s.name===o.lastProcessStage)||stageDefs().find(s=>s.active&&s.type==='process');if(!stage)throw Error('Belum ada tahap proses aktif.');o.stageHistory=[...(o.stageHistory||[]),{at:now(),actor:actor(),from:o.stage,to:stage.name,note:f.reason}];Object.assign(o,{stageId:stage.id,stage:stage.name,outcome:'Aktif',entered:now(),slaDays:Number(stage.sla),reopenReason:f.reason});delete o.closed;record('Buka kembali Opportunity',id,f.reason)})};
const pocWriteFunctions=['createLead','leadPipelineActions','leadBeginQualification','qualify','assessment','leadIdentityEdit','leadEditSource','convertLeadCustomer','closeLead','newOpp','changeStage','closeOpp','bankSelectStage','editOpportunity','reopenRecord','returnLeadQualified','newTask','editTask','cancelTask','activityForm','approveVisit','reviewCorrection','reassign','directCustomer','changeCustomerStatus','c360Edit','c360ContextEdit','c360UploadForm','c360CreateOpportunity','c360LaunchCrossSell','c360Task','applicationForm','masterForm','reorderStage','escalationForm','leadWorkflowConfig'];
for(const name of pocWriteFunctions){const before=globalThis[name];if(typeof before==='function')globalThis[name]=function(){if(pocReadOnly())return toast('Role ini memiliki akses baca data operasional.');return before.apply(this,arguments)}}
const pocApiBefore=api;
api=async function(path,data,method){if(pocReadOnly()&&(method||(data?'POST':'GET'))!=='GET'&&['sync','convert','photo','customer-documents','escalation','config'].includes(path.split('?')[0]))throw Error('Role ini hanya memiliki akses baca data operasional.');return pocApiBefore(path,data,method)};
const pocRecordBefore=record;
record=function(){if(pocReadOnly()){if(serverBase)applyServer({data:clone(serverBase),user:authUser,revision:serverRevision});return toast('Akses baca: perubahan operasional tidak disimpan.')}return pocRecordBefore.apply(this,arguments)};
const pocRenderBefore=render;
render=function(){pocRenderBefore();pocAccessUI()};
const pocContentBefore=renderContent;
renderContent=function(){if(view==='Target & Kinerja')document.querySelector('#app').innerHTML=pocPerformanceScreen();else if(view==='Kesiapan POC'&&authUser?.role!=='AO')document.querySelector('#app').innerHTML=pocEvidenceScreen();else pocContentBefore();if(!authUser||journey)return;
 if(view==='Monitoring'){const app=document.querySelector('#app');app.insertAdjacentHTML('afterbegin',pocPerformancePanel(false));if(authUser.role!=='AO')app.insertAdjacentHTML('beforeend','<div class="actions">'+btn('Kesiapan POC',"go('Kesiapan POC')")+'</div>');pocLoadPerformance();}
 if(view==='Target & Kinerja')pocLoadPerformance();if(view==='Kesiapan POC')pocLoadEvidence();
 if(view==='Opportunity detail'){const o=opp(focus);if(o?.outcome==='Won')document.querySelector('#app').insertAdjacentHTML('beforeend',detailPanel('Realisasi dummy terkonfirmasi',detailFacts([['Nominal realisasi',o.realizedAmount?rup(o.realizedAmount):'Belum dikonfirmasi'],['Tanggal',o.realizedAt||'Belum diisi'],['Referensi',o.realizationReference||'Belum diisi']])+(!pocReadOnly()?btn('Catat / koreksi realisasi',pocCall('pocRealizationForm',o.id),true):'')+'<p class="hint">Nominal pipeline tidak otomatis menjadi nominal realisasi. Konfirmasi ini manual dan menggunakan data dummy.</p>'));}
 if(mobile&&view==='Home'){const grid=document.querySelector('.homemenus');if(grid)grid.insertAdjacentHTML('beforeend','<button onclick="go(\'Target & Kinerja\')"><strong>Target & Kinerja</strong><small>Target, pencapaian dan bukti hasil</small></button>'+(authUser.role!=='AO'?'<button onclick="go(\'Kesiapan POC\')"><strong>Kesiapan POC</strong><small>Konsistensi data dan UAT</small></button>':''));}
 if(view==='Pengaturan')document.querySelector('#app').insertAdjacentHTML('beforeend',detailPanel('POC dua cabang',btn('Target & Kinerja',"go('Target & Kinerja')")+(authUser.role!=='AO'?btn('Kesiapan POC',"go('Kesiapan POC')"):'')+'<p>Seluruh data dummy. Tidak ada integrasi ke sistem Bank.</p>'));pocAccessUI();};
for(const route of ['Target & Kinerja','Kesiapan POC'])if(typeof workspaceLocationRoutes!=='undefined')workspaceLocationRoutes.push(route);
if(typeof workspaceLocationFields!=='undefined')workspaceLocationFields.push(['pocPeriod',()=>pocPeriod,v=>pocPeriod=/^\d{4}-(0[1-9]|1[0-2])$/.test(v)?v:pocPeriod],['pocScope',()=>pocScope,v=>pocScope=['branch','all'].includes(v)?v:'branch']);
function pocTargetCards(rows,ao=false,canSet=false){return '<div class="poc-target-cards">'+rows.map(r=>'<article class="poc-target-card"><h3>'+E(ao?r.name:r.branch)+'</h3>'+(ao?'<small>'+E(r.branch)+'</small>':'<small>'+r.configured+' / '+r.aoCount+' AO memiliki target</small>')+'<dl>'+[['Kredit','credit'],['Dana','funding'],['Layanan','service']].map(([label,key])=>'<div><dt>'+label+'</dt><dd>'+pocCell(r[key],r.target?.[key])+'</dd></div>').join('')+'<div><dt>Task selesai / target</dt><dd>'+r.completed+' / '+(r.target?.completed??'—')+'</dd></div><div><dt>Task overdue</dt><dd>'+r.overdue+'</dd></div></dl>'+(ao&&canSet&&r.branch===activeBranch&&r.eligibleTarget?btn('Atur target',pocCall('pocTargetForm',r.id)):'')+'</article>').join('')+'</div>'}
const pocPanelDesktop=pocPerformancePanel;
pocPerformancePanel=function(full=false){const html=pocPanelDesktop(full);if(!mobile)return html;const data=pocPerformanceCache.get(pocKey('performance'))?.data;if(!data)return html;let index=0;return html.replace(/<div class="scrolltable"><table class="datatable poc-table">[\s\S]*?<\/table><\/div>/g,()=>index++===0?pocTargetCards(data.branchRows):pocTargetCards(data.rows,true,data.canSetTargets))};
const pocEvidenceDesktop=pocEvidenceScreen;
pocEvidenceScreen=function(){const html=pocEvidenceDesktop();if(!mobile)return html;const data=pocEvidenceCache.get(pocUatCacheKey())?.checks;if(!data)return html;return html.replace(/<div class="scrolltable"><table class="datatable">[\s\S]*?<\/table><\/div>/,'<div class="poc-target-cards">'+data.accounts.map(m=>'<article class="poc-target-card"><h3>'+E(m.name)+'</h3><small>'+E(m.id)+'</small><p>'+E(m.role)+'</p><p>'+E(m.branches.join(' · '))+'</p></article>').join('')+'</div>')};
const pocNavigationBefore=navigationParent;
navigationParent=function(route,isMobile=mobile){return isMobile&&['Target & Kinerja','Kesiapan POC'].includes(route)?'Home':pocNavigationBefore(route,isMobile)};
const pocRouteBefore=workspaceRouteAvailable;
workspaceRouteAvailable=function(route,id,data){if(route==='Kesiapan POC'&&authUser?.role==='AO')return false;return pocRouteBefore(route,id,data)};
